//! Scheduling 100k cards (TASK-0019). Data is generated by a fixed LCG so runs are comparable.

#![allow(missing_docs)] // `criterion_group!` generates an undocumented public function

use std::hint::black_box;

use criterion::{Criterion, criterion_group, criterion_main};
use studyfrog_core::memory::{MemState, Sm2State};
use studyfrog_core::review::Rating;
use studyfrog_srs::fsrs::{interval_days, next_state};
use studyfrog_srs::params::{Params, params_default};
use studyfrog_srs::sm2::sm2_next;

const CARDS: usize = 100_000;

/// Deterministic pseudo-random sequence (Numerical Recipes LCG), no dependency needed.
fn lcg(seed: &mut u32) -> u32 {
    *seed = seed.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
    *seed >> 8
}

fn rating(n: u32) -> Rating {
    match n % 4 {
        0 => Rating::Again,
        1 => Rating::Hard,
        2 => Rating::Good,
        _ => Rating::Easy,
    }
}

fn fsrs_cards() -> Vec<(MemState, Rating, f32)> {
    let mut seed = 1;
    (0..CARDS)
        .map(|_| {
            let state = MemState {
                stability: 0.5 + (lcg(&mut seed) % 4000) as f32 / 10.0,
                difficulty: 1.0 + (lcg(&mut seed) % 900) as f32 / 100.0,
            };
            (state, rating(lcg(&mut seed)), (lcg(&mut seed) % 365) as f32)
        })
        .collect()
}

fn sm2_cards() -> Vec<(Sm2State, Rating)> {
    let mut seed = 2;
    (0..CARDS)
        .map(|_| {
            let state = Sm2State {
                ease: 1.3 + (lcg(&mut seed) % 150) as f32 / 100.0,
                repetitions: lcg(&mut seed) % 10,
                interval_days: 1 + lcg(&mut seed) % 400,
            };
            (state, rating(lcg(&mut seed)))
        })
        .collect()
}

fn schedule_fsrs(cards: &[(MemState, Rating, f32)], p: &Params) -> u64 {
    cards
        .iter()
        .map(|(s, r, elapsed)| u64::from(interval_days(&next_state(s, *r, *elapsed, p), p)))
        .sum()
}

fn schedule_sm2(cards: &[(Sm2State, Rating)]) -> u64 {
    cards
        .iter()
        .map(|(s, r)| u64::from(sm2_next(s, *r, 36500).interval_days))
        .sum()
}

fn bench_scheduling(c: &mut Criterion) {
    let (fsrs, sm2, p) = (fsrs_cards(), sm2_cards(), params_default());
    c.bench_function("fsrs_schedule_100k", |b| {
        b.iter(|| schedule_fsrs(black_box(&fsrs), &p))
    });
    c.bench_function("sm2_schedule_100k", |b| {
        b.iter(|| schedule_sm2(black_box(&sm2)))
    });
}

criterion_group!(benches, bench_scheduling);
criterion_main!(benches);
